import { BrowserRouter,Route,Routes,Navigate } from 'react-router-dom';import { Layout } from './components/Layout';import { AdminLayout } from './components/AdminLayout';import Home from './pages/loja/Home';import Catalogo from './pages/loja/Catalogo';import Produto from './pages/loja/Produto';import Carrinho from './pages/loja/Carrinho';import Checkout from './pages/loja/Checkout';import Confirmacao from './pages/loja/Confirmacao';import Acompanhar from './pages/loja/Acompanhar';import Login from './pages/publica/Login';import MinhaConta from './pages/publica/MinhaConta';import {Sobre,Contato,Politica,Termos,Blog} from './pages/publica/SimplePages';import {Dashboard,Produtos,Pedidos,Clientes,Categorias,Cupons,Avaliacoes,Configuracoes,Contatos,Relatorios,Usuarios} from './pages/admin/AdminPages';
export default function App(){return <BrowserRouter><Routes><Route element={<Layout/>}><Route index element={<Home/>}/><Route path="catalogo" element={<Catalogo/>}/><Route path="produto/:slug" element={<Produto/>}/><Route path="carrinho" element={<Carrinho/>}/><Route path="checkout" element={<Checkout/>}/><Route path="pedido-confirmado/:numero" element={<Confirmacao/>}/><Route path="acompanhar" element={<Acompanhar/>}/><Route path="sobre" element={<Sobre/>}/><Route path="contato" element={<Contato/>}/><Route path="privacidade" element={<Politica/>}/><Route path="termos" element={<Termos/>}/><Route path="blog" element={<Blog/>}/><Route path="login" element={<Login/>}/><Route path="minha-conta" element={<MinhaConta/>}/></Route><Route path="admin" element={<AdminLayout/>}><Route index element={<Dashboard/>}/><Route path="produtos" element={<Produtos/>}/><Route path="pedidos" element={<Pedidos/>}/><Route path="clientes" element={<Clientes/>}/><Route path="categorias" element={<Categorias/>}/><Route path="cupons" element={<Cupons/>}/><Route path="avaliacoes" element={<Avaliacoes/>}/><Route path="configuracoes" element={<Configuracoes/>}/><Route path="contatos" element={<Contatos/>}/><Route path="relatorios" element={<Relatorios/>}/><Route path="usuarios" element={<Usuarios/>}/></Route><Route path="*" element={<Navigate to="/"/>}/></Routes></BrowserRouter>}
